import pypdf, re

paths = {
 2019: "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_32/3M_2019_10K.pdf",
 2020: "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_32/3M_2020_10K.pdf",
 2021: "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_32/3M_2021_10K.pdf",
}

for yr, p in paths.items():
    reader = pypdf.PdfReader(p)
    hits = []
    for i, page in enumerate(reader.pages):
        t = page.extract_text() or ""
        if "Net cash provided by operating activities" in t and re.search(r"\$", t):
            hits.append(i)
    print(yr, "pages with operating-activities line:", hits)

